import type { Bundle } from '@specflow/core';

export function generateClaudeMd(bundle: Bundle, projectName: string): string {
  const data = bundle.data;
  const lines: string[] = [
    `# ${projectName}`,
    '',
    '> This file is generated by SpecFlow AI. Last sync: ' + bundle.createdAt,
    '> Bundle version: ' + bundle.version,
    '',
    '## Project Context',
    '',
    `**Stage:** ${data.overview.stage}`,
    `**Description:** ${data.overview.description}`,
    '',
    '## Quick Reference',
    '',
    'Read these files in order for full project context:',
    '',
    '1. `docs/spec-flow/00_overview.md` — Project overview',
    '2. `docs/spec-flow/01_product_spec.md` — Product specifications',
    '3. `docs/spec-flow/03_technical_constraints.md` — Technical constraints',
    '4. `docs/spec-flow/05_task_breakdown.md` — Task breakdown',
    '5. `docs/spec-flow/06_agent_instructions.md` — Agent operating instructions',
    '',
    '## Critical Rules',
    '',
    '- Always check `docs/spec-flow/07_open_questions.md` before making assumptions',
    '- Follow task order in `docs/spec-flow/05_task_breakdown.md`',
    '- Adhere to constraints in `docs/spec-flow/03_technical_constraints.md`',
    '- Reference `docs/spec-flow/08_decision_log.md` for past decisions',
    '',
    '## Open Questions',
    '',
  ];

  const openQuestions = data.openQuestions?.filter(q => q.status === 'open') ?? [];
  if (openQuestions.length > 0) {
    for (const q of openQuestions) {
      lines.push(`- [ ] ${q.question} (${q.category})`);
    }
  } else {
    lines.push('No open questions.');
  }

  lines.push('');
  lines.push('---');
  lines.push(`Generated by SpecFlow AI on ${bundle.createdAt}`);

  return lines.join('\n');
}
